//! The built-in synthetic demonstration.
//!
//! The demo exists so that someone can see what a bundle looks like before they have
//! any data of their own. Everything it produces is generated by this file. It is
//! labelled `synthetic: true` in the manifest, it says so in a banner at the top of
//! the report, and it says so in its own assumptions and limitations. There is no
//! configuration that makes a demo bundle look like a measured one.
//!
//! The problem is a small instrument calibration: a response that is supposed to be
//! linear in a concentration, drifting slowly with time, on top of a baseline.
//!
//! The concentrations are cycled through a fixed set of levels rather than run in
//! increasing order, which is what keeps the gain separable from the drift. The
//! elapsed time still spans nearly fifty minutes while the concentration spans about
//! one unit, so the design columns differ in scale by more than an order of
//! magnitude and the problem is mildly ill conditioned: generalized cross-validation
//! has something real to do, and the report has something honest to say.

use std::fmt::Write as _;

use rand_chacha::ChaCha20Rng;
use rand_core::RngCore;
use serde_json::json;

use crate::canonical;
use crate::error::Result;
use crate::ingest::{self, Problem};
use crate::numeric::bootstrap_stream;

/// The seed for the synthetic noise. Fixed, so `ordinata demo` is the same demo every
/// time and two people can compare bundles.
const DEMO_NOISE_SEED: u64 = 20_240_617;

/// The truth the synthetic data was generated from. A real problem never has this.
const TRUE_BASELINE: f64 = 0.42;
const TRUE_DRIFT: f64 = 0.015;
const TRUE_GAIN: f64 = 2.35;

const OBSERVATIONS: usize = 24;

/// A uniform double in `[0, 1)`, from the top 53 bits of a `ChaCha` word.
fn uniform(rng: &mut ChaCha20Rng) -> f64 {
    #[allow(clippy::cast_precision_loss)]
    let bits = (rng.next_u64() >> 11) as f64;
    bits * (1.0 / 9_007_199_254_740_992.0) // 2^-53
}

/// A standard normal draw, by the Box-Muller transform.
///
/// Spelled out rather than pulled from a distribution crate so that the demo's data
/// is reproducible from its seed and this file alone.
fn standard_normal(rng: &mut ChaCha20Rng) -> f64 {
    // `uniform` can return exactly zero, and ln(0) is not finite, so it is nudged off
    // the boundary. The shift is far below the noise scale and cannot bias anything
    // that matters at double precision.
    let u1 = uniform(rng).max(f64::MIN_POSITIVE);
    let u2 = uniform(rng);
    (-2.0 * u1.ln()).sqrt() * (std::f64::consts::TAU * u2).cos()
}

/// Generate the three synthetic input files, exactly as a user would have written
/// them, and load them through the ordinary ingestion path. The demo takes no
/// shortcut that user data does not also take.
///
/// # Errors
///
/// Returns an error only if the generated project fails Ordinata's own validation,
/// which would be a bug in this file.
pub fn demo_problem() -> Result<Problem> {
    // Cycled rather than ramped. Running the concentrations in increasing order would
    // make them a near-exact function of elapsed time, and gain and drift would stop
    // being separable at all -- which is a real experimental mistake, but it makes for
    // a demo whose estimate is mostly prior.
    const LEVELS: [f64; 6] = [0.10, 0.55, 0.25, 1.20, 0.40, 0.85];

    let mut rng = bootstrap_stream(DEMO_NOISE_SEED);

    let mut design = String::from("observation_id,baseline,drift,gain\n");
    let mut observations = String::from("observation_id,value,standard_error\n");

    for i in 0..OBSERVATIONS {
        #[allow(clippy::cast_precision_loss)]
        let step = i as f64;

        let concentration = LEVELS[i % LEVELS.len()];
        let minutes = 2.0 * step + 0.35 * uniform(&mut rng);

        // Heteroscedastic: a larger response is measured less precisely.
        let standard_error = 0.02 + 0.01 * concentration;

        let truth = TRUE_BASELINE + TRUE_DRIFT * minutes + TRUE_GAIN * concentration;
        let observed = truth + standard_error * standard_normal(&mut rng);

        let id = format!("run-{i:02}");
        let _ = writeln!(
            design,
            "{id},1,{},{}",
            crate::bundle::format_number(minutes),
            crate::bundle::format_number(concentration)
        );
        let _ = writeln!(
            observations,
            "{id},{},{}",
            crate::bundle::format_number(observed),
            crate::bundle::format_number(standard_error)
        );
    }

    let project = json!({
        "schemaVersion": 1,
        "title": "Synthetic instrument calibration (Ordinata demo)",
        "description": "A demonstration bundle produced by `ordinata demo`. The observations were generated by Ordinata from a known linear model with known noise. They are not measurements of anything.",
        "designCsv": "design.csv",
        "observationsCsv": "observations.csv",
        "regularization": {
            "mode": "gcv",
            "minLambda": 1e-6,
            "maxLambda": 1e2,
            "steps": 41
        },
        "uncertainty": {
            "method": "both",
            "confidenceLevel": 0.95,
            "bootstrapSamples": 2000,
            "bootstrapSeed": 7
        },
        "assumptions": [
            "The response is linear in the baseline, the elapsed time, and the concentration, with no interaction between them.",
            "The standard error given for each observation is the true standard deviation of that observation's noise.",
            "The noise on each observation is independent of the noise on every other one.",
            "The concentrations and elapsed times in the design are known exactly and carry no error of their own."
        ],
        "limitations": [
            "This data is synthetic. It was generated by Ordinata and measures nothing in the world.",
            "Elapsed time spans about fifty minutes while concentration spans about one unit, so the design columns differ sharply in scale and the problem is mildly ill conditioned. The uniform penalty used here therefore shrinks the parameters unevenly.",
            "The regularized estimate is pulled toward the prior, and the analytic interval describes the spread of that pulled estimate, not the distance from it to the truth.",
            "A lambda chosen by generalized cross-validation is the best value on the declared grid, which is not the same as the best value."
        ],
        "sources": [
            {
                "label": "Generated by `ordinata demo`; the true parameters are baseline 0.42, drift 0.015 per minute, gain 2.35 per unit concentration.",
                "date": "2026-07-13"
            }
        ],
        "validation": {
            "weightedRmseMax": {
                "value": 2.0,
                "source": "Demonstration threshold. A weighted RMSE far above 1 would mean the declared standard errors do not describe the residuals."
            },
            "conditionNumberMax": {
                "value": 5000.0,
                "source": "Demonstration threshold, chosen to be met by this design."
            }
        }
    });

    let project_bytes = canonical::pretty_bytes(&project)?;
    ingest::load_from_bytes(
        &project_bytes,
        design.as_bytes(),
        observations.as_bytes(),
        true,
    )
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::panic, clippy::expect_used)]
    use super::*;

    #[test]
    fn the_demo_problem_loads_and_is_labelled_synthetic() {
        let problem = demo_problem().unwrap();
        assert!(
            problem.synthetic,
            "a demo bundle must declare itself synthetic"
        );
        assert_eq!(problem.rows(), OBSERVATIONS);
        assert_eq!(problem.parameters, vec!["baseline", "drift", "gain"]);
    }

    #[test]
    fn the_demo_is_the_same_demo_every_time() {
        let a = demo_problem().unwrap();
        let b = demo_problem().unwrap();
        assert_eq!(
            a.values, b.values,
            "the synthetic data must be reproducible"
        );
        assert_eq!(a.design, b.design);
    }

    #[test]
    fn the_demo_says_it_is_synthetic_in_its_own_words() {
        let problem = demo_problem().unwrap();
        let text = problem.limitations.join(" ").to_lowercase();
        assert!(
            text.contains("synthetic"),
            "the limitations must say so in plain language, not only in a flag"
        );
    }

    #[test]
    fn the_demo_recovers_its_own_truth_to_within_its_own_stated_uncertainty() {
        // A fixed absolute tolerance would be meaningless here: `drift` is 0.015 and
        // `gain` is 2.35, so any single number is either vacuous for one or
        // impossible for the other. The right scale is the one the fit itself
        // reports. Checking against it tests two things at once: that the estimates
        // land near the truth, and that the standard errors are the right size to say
        // so. A standard error that came out ten times too large would pass a loose
        // absolute check and fail this one.
        let problem = demo_problem().unwrap();
        let solution = crate::solve::solve(&problem).unwrap();
        assert_eq!(problem.parameters, vec!["baseline", "drift", "gain"]);

        for (index, (name, truth)) in [
            ("baseline", TRUE_BASELINE),
            ("drift", TRUE_DRIFT),
            ("gain", TRUE_GAIN),
        ]
        .iter()
        .enumerate()
        {
            let estimate = solution.estimates[index];
            let standard_error = solution.analytic.standard_errors[index];
            let deviations = (estimate - truth).abs() / standard_error;
            assert!(
                deviations < 4.0,
                "{name} came out as {estimate} +/- {standard_error}, which is {deviations:.1} standard errors from the {truth} it was generated from"
            );
        }
    }

    #[test]
    fn the_demo_is_identifiable_and_publishes_uncertainty() {
        // The whole point of cycling the concentration levels: the design has full
        // rank, so Ordinata is willing to say something about the uncertainty.
        let problem = demo_problem().unwrap();
        let solution = crate::solve::solve(&problem).unwrap();
        assert_eq!(solution.rank, 3, "the demo design must be identifiable");
        assert_eq!(
            solution.analytic.status,
            crate::solve::UncertaintyStatus::Emitted
        );
        assert_eq!(
            solution.bootstrap.status,
            crate::solve::UncertaintyStatus::Emitted
        );
    }
}
